#include <fstream>

uint64_t independent(const vector<int>&word){
 int n=word.size()+2;vector<unsigned> rows(n);rows[0]=2;
 for(int i=0;i<int(word.size());i++){
 for(int j=0;j<2;j++){if(word[i]>>j&1)rows[j]|=1u<<(i+2);else rows[i+2]|=1u<<j;}
 for(int j=i+1;j<int(word.size());j++)rows[i+2]|=1u<<(j+2);
 }
 vector<uint64_t> dp((1u<<n)*n);for(int i=0;i<n;i++)dp[(1u<<i)*n+i]=1;
 for(unsigned mask=1;mask<(1u<<n);mask++)for(int j=0;j<n;j++)if(mask>>j&1){
 uint64_t x=dp[mask*n+j];if(!x)continue;unsigned next=rows[j]&~mask;
 while(next){unsigned b=next&-next;next-=b;int k=__builtin_ctz(b);dp[(mask|b)*n+k]+=x;}}
 uint64_t h=0;for(int j=0;j<n;j++)h+=dp[((1u<<n)-1)*n+j];return h;
}
int main(int argc,char**argv){ifstream f(argv[1],ios::binary);unsigned char bytes[4];uint64_t total=0,subset=0;unsigned ix=0;
 while(f.read((char*)bytes,4)){uint32_t code=0;for(int j=0;j<4;j++)code|=uint32_t(bytes[j])<<(8*j);uint64_t h=2*uint64_t(ix)+1;ix++;
 if(code==0xffffffff)continue;int m=code>>28;vector<int>word(m);for(int i=m-1;i>=0;i--){word[i]=code&3;code>>=2;}
 V v=initial;for(int c:word){V w={};for(auto e:E[c])w[e.second]+=v[e.first];v=w;}
 uint64_t out=0;for(int i=0;i<D;i++)out+=v[i]*accept[i];if(out!=h){cerr<<"transfer fail "<<h;return 1;}total++;
 if(h<=1001 || ix%3907==0){if(independent(word)!=h){cerr<<"subset fail "<<h;return 1;}subset++;}}
 cout<<"{\"all_certificate_transfer_replays\":"<<total<<",\"independent_subset_dp_witnesses\":"<<subset<<"}\n";
}
